{* Code generated by xgen. DO NOT EDIT.
    Source: xgen/specs/organisms/pricing-tiers.json
    A section with a heading and one PricingCard per plan. Axes: layout (grid, stack), columns, emphasis, billing (off: no toggle; monthly or annual: a toggle with that choice selected, and the prices of that period), density, tone.
    Props (p): id, title, plans, labels, billingLabels, layout, cols, emphasis, billing, tone, density, landmarkLabel. *}
{var $v_id = ($p['id'] ?? null)}
{var $v_title = ($p['title'] ?? null)}
{var $v_plans = ($p['plans'] ?? null)}
{var $v_labels = ($p['labels'] ?? null)}
{var $v_billingLabels = ($p['billingLabels'] ?? null)}
{var $v_layout = ($p['layout'] ?? 'grid')}
{var $v_cols = ($p['cols'] ?? '1-3')}
{var $v_emphasis = ($p['emphasis'] ?? 'auto')}
{var $v_billing = ($p['billing'] ?? 'off')}
{var $v_tone = ($p['tone'] ?? 'default')}
{var $v_density = ($p['density'] ?? 'default')}
{var $v_landmarkLabel = ($p['landmarkLabel'] ?? null)}
{capture $c_7}
  {if ui_t(!(ui_eq($v_billing, 'off')))}
    {capture $c_5}
      {capture $c_3}
        {capture $c_1}
          {=ui_text(ui_get($v_billingLabels, ['monthly']))}
        {/capture}
        {=ui_include('blocks/switcher-item.latte', ['p' => ['active' => ui_eq($v_billing, 'monthly')], 'children' => $c_1])|noescape}
        {capture $c_2}
          {=ui_text(ui_get($v_billingLabels, ['annual']))}
        {/capture}
        {=ui_include('blocks/switcher-item.latte', ['p' => ['active' => ui_eq($v_billing, 'annual')], 'children' => $c_2])|noescape}
      {/capture}
      {=ui_include('blocks/switcher.latte', ['p' => ['label' => ui_get($v_billingLabels, ['label'])], 'children' => $c_3])|noescape}
      {capture $c_4}
        {=ui_text(ui_get($v_billingLabels, ['save']))}
      {/capture}
      {=ui_include('ui/badge/badge.latte', ['p' => ['Variant' => 'default', 'Size' => 'default'], 'children' => $c_4])|noescape}
    {/capture}
    {=ui_include('ui/group/group.latte', ['p' => ['Gap' => '4', 'Align' => 'center', 'Justify' => 'center', 'Class' => 'flex-wrap', 'Attrs' => ui_attrs(['data-testid', 'billing'])], 'children' => $c_5])|noescape}
  {/if}
  {capture $c_6}
    {foreach ui_l($v_plans) as $v_plan}
      {=ui_include('blocks/pricing-card.latte', ['p' => ['plan' => $v_plan, 'labels' => $v_labels, 'emphasis' => $v_emphasis, 'billing' => (ui_t(ui_eq($v_billing, 'annual')) ? 'annual' : 'monthly'), 'density' => (ui_t(ui_eq($v_density, 'compact')) ? 'compact' : 'default')]])|noescape}
    {/foreach}
  {/capture}
  {=ui_include('ui/grid/grid.latte', ['p' => ['Cols' => ui_s((ui_t(ui_eq($v_layout, 'stack')) ? '1' : ui_fit_cols($v_cols, ui_len($v_plans)))), 'Class' => 'gap-4', 'Attrs' => ui_attrs(['data-testid', 'tiers'])], 'children' => $c_6])|noescape}
{/capture}
{=ui_include('blocks/section-frame.latte', ['p' => ['id' => $v_id, 'title' => $v_title, 'tone' => $v_tone, 'density' => $v_density, 'measure' => (ui_t(ui_eq($v_layout, 'stack')) ? 'md' : 'default'), 'landmarkLabel' => $v_landmarkLabel], 'children' => $c_7])|noescape}
